import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"Starting a Flow via webhook","description":"Trigger a Flow from an outside system.","frontmatter":{"title":"Starting a Flow via webhook","description":"Trigger a Flow from an outside system."},"headers":[],"relativePath":"en/flows/webhook-trigger.md","filePath":"en/flows/webhook-trigger.md","lastUpdated":1787319236000}'),i={name:"en/flows/webhook-trigger.md"};function r(n,e,l,h,d,c){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="starting-a-flow-via-webhook" tabindex="-1">Starting a Flow via webhook <a class="header-anchor" href="#starting-a-flow-via-webhook" aria-label="Permalink to &quot;Starting a Flow via webhook&quot;">​</a></h1><p>The <strong>Webhook</strong> trigger starts a Flow when an outside system sends a request. This is how you connect ApptiveGrid to any other tool.</p><div class="tip custom-block"><p class="custom-block-title">Don&#39;t confuse it with outgoing webhooks</p><table tabindex="0"><thead><tr><th>Direction</th><th>Set up in</th></tr></thead><tbody><tr><td><strong>Outside system → ApptiveGrid</strong></td><td>Flow trigger <em>Webhook</em> — this page</td></tr><tr><td><strong>ApptiveGrid → outside system</strong></td><td><a href="/en/integrationen/webhooks">Webhooks</a> in Space settings</td></tr></tbody></table></div><h2 id="setting-it-up" tabindex="-1">Setting it up <a class="header-anchor" href="#setting-it-up" aria-label="Permalink to &quot;Setting it up&quot;">​</a></h2><ol><li>Create a new Flow.</li><li>In the <strong>Trigger</strong> tab, choose <strong>Webhook</strong>.</li><li>Open the step — the address is shown there.</li></ol><p>The section is called <strong>Link to start the Flow</strong>:</p><blockquote><p><em>To start the Flow, send a POST request to the following URL:</em></p></blockquote><h2 id="passing-data-along" tabindex="-1">Passing data along <a class="header-anchor" href="#passing-data-along" aria-label="Permalink to &quot;Passing data along&quot;">​</a></h2><p><strong>Send POST request</strong></p><blockquote><p><em>Send data in JSON format via a POST request to the link above to start the Flow.</em></p></blockquote><p>The submitted JSON data is available to all subsequent steps. → <a href="/en/flows/daten-zwischen-schritten">Data between steps</a></p><h2 id="registering-it-in-an-outside-system" tabindex="-1">Registering it in an outside system <a class="header-anchor" href="#registering-it-in-an-outside-system" aria-label="Permalink to &quot;Registering it in an outside system&quot;">​</a></h2><p><strong>Use as webhook</strong></p><blockquote><p><em>Enter the URL as a webhook in other services. This automatically starts the workflow when the corresponding service triggers the webhook.</em></p></blockquote><p>Practically anywhere a service asks for a &quot;webhook URL&quot; — form services, shop systems, payment providers, automation platforms, monitoring tools.</p><h2 id="testing" tabindex="-1">Testing <a class="header-anchor" href="#testing" aria-label="Permalink to &quot;Testing&quot;">​</a></h2><p><strong>Test webhook</strong></p><blockquote><p><em>You can test the webhook by sending a sample JSON payload:</em></p></blockquote><p>Enter sample data under <strong>JSON payload</strong> and click <strong>Test now</strong>.</p><div class="tip custom-block"><p class="custom-block-title">Test with real data</p><p>For the sample payload, use as closely as possible what the outside system actually sends. Many services show an example in their own interface — copy it here.</p><p>Otherwise you build the Flow against a made-up structure, and it fails on the first real call.</p></div><p>Alternatively, the editor offers <strong>Start with test data</strong>: <em>Provide sample data</em>.</p><p>→ <a href="/en/flows/testen">Testing Flows</a></p><h2 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">The webhook URL is a credential</p><p>Anyone who knows the address can start the Flow — as many times as they like. There&#39;s no additional check on who&#39;s sending the request.</p><p>Treat it like a password:</p><ul><li>not in public repositories</li><li>not in chats or on slides</li><li>store it only in the target system</li></ul></div><div class="warning custom-block"><p class="custom-block-title">Consider what the Flow does</p><p>A Flow that creates entries or sends emails does so on every call. If the URL ends up in the wrong hands, or a faulty system calls it repeatedly, a correspondingly large number of operations follow.</p><p>Check the <a href="/en/flows/durchlaufhistorie">history</a> regularly to make sure the number of runs is plausible.</p></div><p>All active access points of a Space are listed under <a href="/en/zusammenarbeit/externe-links">External links at a glance</a> — the type shown there is <strong>Start Flow</strong>.</p><div class="tip custom-block"><p class="custom-block-title">Remove webhooks you no longer need</p><p>A webhook stays active as long as the Flow exists — even if the connecting system was shut down long ago. Go through the links overview regularly.</p></div><h2 id="typical-uses" tabindex="-1">Typical uses <a class="header-anchor" href="#typical-uses" aria-label="Permalink to &quot;Typical uses&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Use case</th><th>Flow</th></tr></thead><tbody><tr><td>Pick up an order from a shop</td><td>Shop calls the webhook, Flow creates an entry</td></tr><tr><td>Process a third-party form</td><td>Service calls the webhook, Flow distributes the data</td></tr><tr><td>Incident report from a monitoring system</td><td>System calls the webhook, Flow notifies and logs</td></tr><tr><td>Nightly import from another system</td><td>Script calls the webhook with data</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">No time-based triggering</p><p>ApptiveGrid has no &quot;every day at 8am&quot; trigger. If you want to start a Flow on a schedule, an external system needs to call the webhook URL at the desired time.</p><p>The <strong>Wait</strong> step doesn&#39;t help here: it measures from the moment the step is reached, not up to a fixed time. → <a href="/en/flows/router-und-parallel">Router and Parallel</a></p></div><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/flows/trigger">Trigger</a></li><li><a href="/en/flows/daten-zwischen-schritten">Data between steps</a></li><li><a href="/en/zusammenarbeit/externe-links">External links at a glance</a></li></ul>',32)])])}const g=t(i,[["render",r]]);export{u as __pageData,g as default};
